-- Seeds a full year of demo data for each template except Payroll (see the
-- plan this was built from - Payroll's data lives in a dedicated schema,
-- not submissions, and has no public view yet). Generated by
-- scripts/generate-demo-seed.js - re-run that script to regenerate rather
-- than hand-editing this file; see its printed summary for exact counts/
-- totals at generation time.

-- Restaurant (Mama's Kitchen): regenerate in place, same form - the old
-- Phase 1 seed (~18 orders over a week) is replaced with a full year so
-- Report's date-range filters (This month / Last 3-6-12 months) actually
-- differ from each other instead of all showing the same handful of rows.
delete from submissions where form_id = '11111111-1111-4111-8111-111111111111';








-- Retail (new): its own Naira-priced catalogue rather than the retail-shop
-- template's literal seeded prices (those are small USD-style decimals,
-- e.g. $15.99, inconsistent with the ₦-whole-number convention every other
-- demo/seed in this app uses).
values (
  '33333333-3333-4333-8333-333333333333',
  'Glow Fashion Retail',
  'A sample retail business, used to power the onboarding demo.',
  'published', true, '7d91d04c-d223-4ef1-a94d-382aa2d31bfe', '{}'::jsonb,
  '[{"id":"order","type":"cart","label":"Order","required":true,"deferCheckout":true,"products":[{"id":"r1","name":"Ankara Maxi Dress","price":"12000","category":"Dresses"},{"id":"r2","name":"Men''s Kaftan","price":"16000","category":"Menswear"},{"id":"r3","name":"Denim Jacket","price":"11000","category":"Outerwear"},{"id":"r4","name":"Leather Sandals","price":"7000","category":"Footwear"},{"id":"r5","name":"Sneakers","price":"15000","category":"Footwear"},{"id":"r6","name":"Beaded Necklace","price":"3500","category":"Accessories"},{"id":"r7","name":"Wristwatch","price":"20000","category":"Accessories"},{"id":"r8","name":"Wireless Earbuds","price":"17000","category":"Electronics"},{"id":"r9","name":"Phone Case","price":"3000","category":"Electronics"},{"id":"r10","name":"Tote Bag","price":"9000","category":"Bags"}]},{"id":"customer_name","type":"text","label":"Customer Name","required":false,"collapsedInCheckout":true},{"id":"phone","type":"phone","label":"Phone","required":false,"collapsedInCheckout":true}]'::jsonb
)
on conflict (id) do nothing;







-- Expenses (new): same field shape as the real 'expenses' template, plus
-- the same settings.reportDateField/reportAmountField/recordKind a real
-- Expenses workspace gets from locations.js's expenseDefaults(), so
-- Report.jsx buckets it by its own `date` field the same way.
values (
  '55555555-5555-4555-8555-555555555555',
  'Kola & Co Ventures',
  'A sample business''s expense records, used to power the onboarding demo.',
  'published', true, '7d91d04c-d223-4ef1-a94d-382aa2d31bfe',
  '{"recordKind":"expense","expenseMode":"business","reportDateField":"date","reportAmountField":"amount"}'::jsonb,
  '[{"id":"amount","type":"number","label":"Amount","required":true},{"id":"category","type":"dropdown","label":"Category","required":true,"options":["Inventory / Stock","Supplies","Transport","Utilities","Rent","Staff","Marketing","Repairs & Maintenance","Equipment","Software & Subscriptions","Professional Services","Taxes / Fees","Food / Entertainment","Bank Charges","Other"]},{"id":"description","type":"text","label":"Description","required":false},{"id":"date","type":"date","label":"Date","required":false},{"id":"time","type":"time","label":"Time","required":false},{"id":"payment_method","type":"dropdown","label":"Payment method","required":false,"options":["Cash","Bank Transfer","Card","POS","Mobile Wallet","Other"]},{"id":"paid_from","type":"dropdown","label":"Paid from","required":false,"options":["Business account","Cash / Till","Personal account","Other"]},{"id":"vendor","type":"text","label":"Vendor / Supplier","required":false},{"id":"notes","type":"longtext","label":"Notes","required":false}]'::jsonb
)
on conflict (id) do nothing;




-- Data Collection (new): a sample "Customer Feedback" form - the blank-
-- canvas Forms template has no preset fields of its own, so this dataset
-- defines its own. No monetary total (a feedback form doesn't have one) -
-- its "volume" is response count and rating distribution instead.
values (
  '77777777-7777-4777-8777-777777777777',
  'Customer Feedback',
  'A sample data-collection form and its responses, used to power the onboarding demo.',
  'published', true, '7d91d04c-d223-4ef1-a94d-382aa2d31bfe', '{}'::jsonb,
  '[{"id":"name","type":"text","label":"Name","required":false},{"id":"email","type":"email","label":"Email","required":false},{"id":"how_heard","type":"dropdown","label":"How did you hear about us?","required":false,"options":["Instagram","Referral","Google","Walk-in","Other"]},{"id":"rating","type":"rating","label":"Rating","required":true,"maxStars":5},{"id":"comments","type":"longtext","label":"Comments","required":false},{"id":"recommend","type":"multiplechoice","label":"Would you recommend us?","required":false,"options":["Yes","No"]}]'::jsonb
)
on conflict (id) do nothing;





-- New demo_datasets rows (Mama's Kitchen's own row from Phase 2 already
-- points at the same, unchanged form id, so it needs no update).
on conflict (id) do nothing;

-- Reporting moves off the Restaurant dataset (previously identical to
-- Sales) onto the new Retail one - matches the onboarding design brief's
-- own example pairing (Sales/Restaurant, Reporting/Retail). Expenses and
-- Data Collection move from a field-shape preview to real report data now
-- that there's something to show.
update demo_routes set demo_dataset_id = '44444444-4444-4444-8444-444444444444', destination = 'report' where entry_intent = 'reporting';
update demo_routes set demo_dataset_id = '66666666-6666-4666-8666-666666666666', destination = 'report' where entry_intent = 'expenses';
update demo_routes set demo_dataset_id = '88888888-8888-4888-8888-888888888888', destination = 'report' where entry_intent = 'data_collection';
